     <script>
       const fields = [
         {
           id: "fullName",
           name: "fullName",
           label: "Full name",
           type: "text",
           autocomplete: "name",
           required: true,
           placeholder: "Alex Morgan",
           validate(value) {
             return value.trim() ? "" : "Error: Enter your full name.";
           },
         },
         {
           id: "email",
           name: "email",
           label: "Email address",
           type: "email",
           autocomplete: "email",
           required: true,
           placeholder: "alex@example.com",
           validate(value) {
             const trimmed = value.trim();
             if (!trimmed) {
               return "Error: Enter your email address.";
             }
             return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)
               ? ""
               : "Error: Enter a valid email address, like alex@example.com.";
           },
         },
         {
           id: "phone",
           name: "phone",
           label: "Phone number",
           type: "tel",
           autocomplete: "tel",
           required: false,
           placeholder: "(555) 123-4567",
           helperText: "Expected format: (555) 123-4567 or 555-123-4567.",
           validate(value) {
             const trimmed = value.trim();
             if (!trimmed) {
               return "";
             }
             return /^(\(\d{3}\)\s?|\d{3}[-.\s]?)\d{3}[-.\s]?\d{4}$/.test(trimmed)
               ? ""
               : "Error: Enter a phone number like (555) 123-4567.";
           },
         },
       ];

       function Field({ id, name, label, type, autocomplete, required, placeholder, helperText }) {
         const helperId = helperText ? `${id}-help` : "";
         const errorId = `${id}-error`;
         const describedBy = [helperId, errorId].filter(Boolean).join(" ");
         const requiredText = required
           ? '<span class="required-mark" aria-hidden="true">*</span>'
           : '<span class="optional-text">(optional)</span>';

         return `
           <div class="form-field">
             <label for="${id}">${label} ${requiredText}</label>
             <input
               id="${id}"
               name="${name}"
               type="${type}"
               autocomplete="${autocomplete}"
               placeholder="${placeholder}"
               ${required ? "required" : ""}
               aria-describedby="${describedBy}"
               aria-invalid="false"
             >
             ${helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : ""}
             <p class="error-message" id="${errorId}"></p>
           </div>
         `;
       }

       function SupportContactForm() {
         return `
           <section class="support-card" aria-labelledby="support-title">
             <p class="eyebrow">Support request</p>
             <h1 id="support-title">Contact support</h1>
             <p class="intro">
               Tell us how to reach you and our support team will follow up as soon as possible.
             </p>
             <form id="support-form" novalidate>
               <p class="required-note"><span aria-hidden="true">*</span> Required fields</p>
               ${fields.map(Field).join("")}
               <button type="submit">Send support request</button>
               <p class="status-message" id="form-status" aria-live="polite"></p>
             </form>
           </section>
         `;
       }

       function App() {
         return SupportContactForm();
       }

       function setError(input, message) {
         const error = document.getElementById(`${input.id}-error`);
         input.setAttribute("aria-invalid", message ? "true" : "false");
         error.textContent = message;
       }

       function validateInput(input) {
         const field = fields.find(({ id }) => id === input.id);
         const message = field.validate(input.value);
         setError(input, message);
         return !message;
       }

       function initializeForm() {
         const form = document.getElementById("support-form");
         const status = document.getElementById("form-status");
         const inputs = fields.map(({ id }) => document.getElementById(id));

         inputs.forEach((input) => {
           input.addEventListener("blur", () => validateInput(input));
           input.addEventListener("input", () => {
             if (input.getAttribute("aria-invalid") === "true") {
               validateInput(input);
             }
             status.textContent = "";
           });
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           status.textContent = "";

           const firstInvalid = inputs.find((input) => !validateInput(input));
           if (firstInvalid) {
             firstInvalid.focus();
             return;
           }

           form.reset();
           inputs.forEach((input) => setError(input, ""));
           status.textContent = "Your support request is ready to send.";
         });
       }

       document.getElementById("main-content").innerHTML = App();
       initializeForm();
     </script>
   </body>
 </html>

