         error.textContent = message;
       }

       function validateInput(input) {
         const field = fields.find(({ id }) => id === input.id);
         const message = field.validate(input.value);
         setError(input, message);
         return !message;
       }

       function initializeForm() {
         const form = document.getElementById("support-form");
         const status = document.getElementById("form-status");
         const inputs = fields.map(({ id }) => document.getElementById(id));

         inputs.forEach((input) => {
           input.addEventListener("blur", () => validateInput(input));
           input.addEventListener("input", () => {
             if (input.getAttribute("aria-invalid") === "true") {
               validateInput(input);
             }
             status.textContent = "";
           });
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           status.textContent = "";

           const firstInvalid = inputs.find((input) => !validateInput(input));
           if (firstInvalid) {
             firstInvalid.focus();
             return;
           }

           form.reset();
           inputs.forEach((input) => setError(input, ""));
           status.textContent = "Your support request is ready to send.";
         });
       }

       document.getElementById("main-content").innerHTML = App();
       initializeForm();
     </script>
   </body>
 </html>

